import React, { useEffect, useRef, useState } from "react";

function App() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);
  const [conversationId, setConversationId] = useState(null);
  const bottomRef = useRef(null);

  // 1️⃣ Create a new conversation on load
  useEffect(() => {
    fetch("http://localhost:3000/api/conversation/new", { method: "POST" })
      .then(res => res.json())
      .then(data => {
        const id = data.conversationId;
        setConversationId(id);

        // Load past messages if any
        fetch(`http://localhost:3000/api/conversation/${id}`)
          .then(res => res.json())
          .then(history => setMessages(history.messages || []));
      });
  }, []);

  // 2️⃣ Auto-scroll when messages update
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // 3️⃣ Send prompt and receive assistant reply
  const sendPrompt = async () => {
    if (!input.trim() || !conversationId) return;

    const userMessage = { role: "user", content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput("");

    // Streaming-ready fetch (backend handles stream: false or true)
    const res = await fetch("http://localhost:3000/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: userMessage.content,
        conversationId,
      }),
    });

    const data = await res.json();

    const aiMessage = { role: "assistant", content: data.reply || "" };
    setMessages(prev => [...prev, aiMessage]);
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.title}>Ollama Local AI Workspace</h1>

      <div style={styles.chatBox}>
        {messages.map((msg, idx) => (
          <div
            key={idx}
            style={{
              ...styles.message,
              ...(msg.role === "user" ? styles.userMessage : styles.aiMessage),
            }}
          >
            {msg.content}
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      <div style={styles.inputRow}>
        <textarea
          rows="2"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type your message..."
          style={styles.textarea}
        />
        <button onClick={sendPrompt} style={styles.button}>
          Send
        </button>
      </div>
    </div>
  );
}

// --- Styles remain the same ---
const styles = {
  page: {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "system-ui, sans-serif",
  },
  title: {
    textAlign: "center",
  },
  chatBox: {
    border: "1px solid #ccc",
    borderRadius: "8px",
    padding: "10px",
    height: "400px",
    overflowY: "auto",
    marginBottom: "10px",
    background: "#f9f9f9",
  },
  message: {
    padding: "10px",
    borderRadius: "6px",
    marginBottom: "8px",
    maxWidth: "70%",
    whiteSpace: "pre-wrap",
  },
  userMessage: {
    background: "#dbeafe",
    marginLeft: "auto",
    textAlign: "right",
  },
  aiMessage: {
    background: "#e5e7eb",
    marginRight: "auto",
  },
  inputRow: {
    display: "flex",
    gap: "10px",
  },
  textarea: {
    flex: 1,
    resize: "none",
    padding: "10px",
    borderRadius: "6px",
  },
  button: {
    padding: "10px 16px",
    borderRadius: "6px",
    border: "none",
    background: "#2563eb",
    color: "#fff",
    cursor: "pointer",
  },
};

export default App;
